function referencePointerPosition(e,canvas){const a=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(100,(e.clientX-a.left)/a.width*100)),y:Math.max(0,Math.min(100,(e.clientY-a.top)/a.height*100))};}
function bindReferenceDrag(canvas){
 if(canvas.id!=='srOriginal')return;
 canvas.addEventListener('pointerdown',e=>{if(e.button!==0||busy||drag||!B.getPixels(current))return;e.preventDefault();const at=referencePointerPosition(e,canvas);drag={start:at,end:at,canvasId:canvas.id,pointerId:e.pointerId};canvas.setPointerCapture(e.pointerId);});
 canvas.addEventListener('pointermove',e=>{if(!drag||drag.canvasId!==canvas.id||drag.pointerId!==e.pointerId)return;drag.end=referencePointerPosition(e,canvas);draw();});
 canvas.addEventListener('pointerup',e=>{if(!drag||drag.canvasId!==canvas.id||drag.pointerId!==e.pointerId)return;drag.end=referencePointerPosition(e,canvas);const r={left:Math.min(drag.start.x,drag.end.x),top:Math.min(drag.start.y,drag.end.y),right:Math.max(drag.start.x,drag.end.x),bottom:Math.max(drag.start.y,drag.end.y)};for(const k of Object.keys(r))r[k]=Math.round(r[k]*10000)/10000;drag=null;if(r.left<r.right&&r.top<r.bottom)applyReference(r);draw();});
 canvas.addEventListener('pointercancel',e=>{if(drag?.canvasId===canvas.id&&drag.pointerId===e.pointerId){drag=null;draw();}});
}
function bindSelectionDrag(canvas){
 if(canvas.id!=='srResult')return;
 canvas.addEventListener('pointerdown',e=>{suppressResultClick=false;if(e.button!==0||busy||drag||!state().result||!B.getPixels(current))return;e.preventDefault();const at=referencePointerPosition(e,canvas);drag={start:at,end:at,canvasId:canvas.id,pointerId:e.pointerId};canvas.setPointerCapture(e.pointerId);});
 canvas.addEventListener('pointermove',e=>{if(!drag||drag.canvasId!==canvas.id||drag.pointerId!==e.pointerId)return;drag.end=referencePointerPosition(e,canvas);draw();});
 canvas.addEventListener('pointerup',e=>{if(!drag||drag.canvasId!==canvas.id||drag.pointerId!==e.pointerId)return;const selectedDrag=drag;selectedDrag.end=referencePointerPosition(e,canvas);drag=null;suppressResultClick=true;try{const s=state();if(busy||!s.result||!B.getPixels(current))return;reviewMask(s);const raw=s.automaticResult||s.result,mask=masks.get(current),box=canvas.getBoundingClientRect(),dx=Math.abs(selectedDrag.end.x-selectedDrag.start.x)/100*box.width,dy=Math.abs(selectedDrag.end.y-selectedDrag.start.y)/100*box.height;
  if(dx>=3&&dy>=3){const x0=Math.min(selectedDrag.start.x,selectedDrag.end.x)/100*canvas.width,y0=Math.min(selectedDrag.start.y,selectedDrag.end.y)/100*canvas.height,x1=Math.max(selectedDrag.start.x,selectedDrag.end.x)/100*canvas.width,y1=Math.max(selectedDrag.start.y,selectedDrag.end.y)/100*canvas.height;selectReviewComponents(inspectComponentsInBox(raw,mask,{x0,y0,x1,y1}));}
  else selectReviewComponent(inspectComponent(raw,mask,{x:selectedDrag.end.x/100*canvas.width,y:selectedDrag.end.y/100*canvas.height}));
 }catch(e){error(e.message);}finally{draw();}});
 canvas.addEventListener('pointercancel',e=>{if(drag?.canvasId===canvas.id&&drag.pointerId===e.pointerId){drag=null;suppressResultClick=true;draw();}});
}
